def load() -> pd.DataFrame:
    import glob, pandas as pd
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201810??T235942_201810??T235942_0201/*.sp3'))
    rows = []
    for fp in files[:1]:
        with open(fp,'r') as f:
            for i,line in enumerate(f):
                if i>300: break
                if line.startswith('*') or line.startswith('P') or line.startswith('PG') or line.startswith('PA'):
                    rows.append({'file':fp,'line_no':i,'text':line.rstrip('\n')})
    return pd.DataFrame(rows).head(50)

def process(omni2):
    import pandas as pd
    df = omni2.copy()
    df['Timestamp'] = pd.to_datetime(df['Timestamp'], utc=True, errors='coerce')
    # keep 2018-10-01 00:00 through 2018-10-10 23:00 inclusive
    start = pd.Timestamp('2018-10-01T00:00:00Z')
    end = pd.Timestamp('2018-10-10T23:00:00Z')
    df = df[(df['Timestamp'] >= start) & (df['Timestamp'] <= end)].sort_values('Timestamp')

    # coerce numeric columns; OMNI2 uses large fill values (e.g., 999.9, 99999.9, 999999.99, 100000) etc.
    non_numeric = {'Timestamp'}
    for c in df.columns:
        if c in non_numeric:
            continue
        df[c] = pd.to_numeric(df[c], errors='coerce')

    # Replace common OMNI2 fill values with NA using per-column thresholds
    fill_vals = {999.9, 999.99, 9999.9, 99999.9, 999999.99, 999999.9, 100000, 1000000}
    for c in df.columns:
        if c == 'Timestamp':
            continue
        s = df[c]
        # exact matches for canonical fills
        df.loc[s.isin(list(fill_vals)), c] = pd.NA
        # also treat absurd magnitudes as missing for select physical vars
        # (but keep indices like AE that can reach ~1000)
        if c.startswith('Proton_flux_'):
            df.loc[df[c] > 1e5, c] = pd.NA
        if c in ['sigma_T_K','sigma_n_N_cm3','sigma_V_km_s','sigma_phi_V_degrees','sigma_theta_V_degrees','sigma_ratio',
                 'Flow_pressure','E_electric_field','Plasma_Beta','Alfen_mach_number','Magnetosonic_Mach_number','Quasy_Invariant']:
            df.loc[df[c] > 1e4, c] = pd.NA

    return df
